// Counts a bounded Q5 local EP0 kernel, not Q6 original matchings.
#include <bits/stdc++.h>
using namespace std;using U=unsigned;using L=unsigned long long;
L permanent(const vector<U>&rows,int n){vector<L>memo(1u<<n,~0ull);memo[0]=1;function<L(U)>go=[&](U mask)->L{L&z=memo[mask];if(z!=~0ull)return z;z=0;int i=n-__builtin_popcount(mask);for(U t=rows[i]&mask;t;t&=t-1)z+=go(mask^(t&-t));return z;};return go((1u<<n)-1);}
L choose(int n,int k){L z=1;for(int i=1;i<=k;i++)z=z*(n-i+1)/i;return z;}
int main(){cout<<"[";bool sep=false;for(int q:{1,7,31}){vector<int>E,O;for(int v=1;v<32;v++)if(v!=q)(__builtin_popcount(U(v))%2?O:E).push_back(v);assert(E.size()==15&&O.size()==15);U adj[15]{};for(int i=0;i<15;i++)for(int j=0;j<15;j++)if(__builtin_popcount(U(E[i]^O[j]))==1)adj[i]|=1u<<j;vector<L>dp(1u<<15),next(dp.size());dp[0]=1;for(int i=0;i<15;i++){next=dp;for(U m=0;m<dp.size();m++)if(dp[m])for(U t=adj[i]&~m;t;t&=t-1)next[m|(t&-t)]+=dp[m];dp.swap(next);}L partial=accumulate(dp.begin(),dp.end(),0ull);vector<U>uni(dp.size());array<L,16>hole{};for(U m=0;m<dp.size();m++){if(m){U b=m&-m;uni[m]=uni[m^b]|adj[__builtin_ctz(b)];}int k=__builtin_popcount(m),free=15-__builtin_popcount(uni[m]);if(free>=k)hole[k]+=choose(free,k);}array<L,16>maxmatch{};for(U em=0;em<dp.size();em++){int k=__builtin_popcount(em);U available=((1u<<15)-1)^uni[em];if(__builtin_popcount(available)<k)continue;for(U om=available;;om=(om-1)&available){if(__builtin_popcount(om)==k){vector<int>os;for(int j=0;j<15;j++)if(!(om>>j&1))os.push_back(j);vector<U>rows;for(int i=0;i<15;i++)if(!(em>>i&1)){U a=0;for(int j=0;j<(int)os.size();j++)if(adj[i]>>os[j]&1)a|=1u<<j;rows.push_back(a);}stable_sort(rows.begin(),rows.end(),[](U a,U b){return __builtin_popcount(a)<__builtin_popcount(b);});maxmatch[k]+=permanent(rows,rows.size());}if(!om)break;}}if(sep)cout<<",";sep=true;cout<<"{\"root\":0,\"odd_hole\":"<<q<<",\"distance\":"<<__builtin_popcount(U(q))<<",\"all_short_partial_matchings\":"<<partial<<",\"short_perfect_matchings\":"<<dp.back()<<",\"independent_balanced_exposed_sets_by_size_per_parity\":{";bool s=false;for(int k=0;k<16;k++)if(hole[k]){if(s)cout<<",";s=true;cout<<"\""<<k<<"\":"<<hole[k];}cout<<"},\"maximal_short_matchings_by_exposed_size_per_parity\":{";bool mm=false;L totalmax=0;for(int k=0;k<16;k++)if(maxmatch[k]){if(mm)cout<<",";mm=true;cout<<"\""<<k<<"\":"<<maxmatch[k];totalmax+=maxmatch[k];}cout<<"},\"maximal_short_matchings_total\":"<<totalmax<<"}";}cout<<"]\n";}
